<?php require __DIR__.'/../app/bootstrap.php';$ref=trim($_GET['reference']??'');if(!$ref){flash('error','Missing payment reference.');header('Location:/wallet.php');exit;}try{$ps=new Paystack($config['paystack']['secret_key'],$config['app_url']);$r=$ps->verify($ref);$d=$r['data']??[];$s=$pdo->prepare('SELECT * FROM funding_transactions WHERE reference=? FOR UPDATE');$pdo->beginTransaction();$s->execute([$ref]);$f=$s->fetch();if(!$f)throw new RuntimeException('Funding record not found.');if($f['status']!=='successful'){if(($d['status']??'')==='success' && (int)($d['amount']??0)===(int)round($f['amount']*100)){$pdo->prepare('UPDATE funding_transactions SET status="successful",provider_reference=? WHERE id=?')->execute([$d['reference']??$ref,$f['id']]);$pdo->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$f['amount'],$f['user_id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description,status) VALUES(?,?,?,?,?,?)')->execute([$f['user_id'],'credit',$f['amount'],'CR-'.$ref,'Wallet funding','successful']);flash('success','Wallet funded successfully.');}else{$pdo->prepare('UPDATE funding_transactions SET status="failed",provider_reference=? WHERE id=?')->execute([$d['reference']??$ref,$f['id']]);flash('error','Payment was not successful or the amount did not match.');}}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error','Payment verification failed.');}header('Location:/wallet.php');exit;
